pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.deal(actor, amount);
        uint256 before = c.getBalance(actor);
        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: amount}() { ok = true; } catch { ok = false; }
        // General rule: either the deposit reverts (overflow) leaving the recorded
        // balance unchanged, or it succeeds and the recorded balance is exactly the
        // sum of the prior balance and the deposited amount.
        assertTrue(ok ? (c.getBalance(actor) == before + amount) : (c.getBalance(actor) == before));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.assume(amount > type(uint256).max / 4); // huge deposit: two of them overflow

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok1;
        try c.addToBalance{value: amount}() { ok1 = true; } catch { ok1 = false; }
        assertTrue(ok1, "first deposit must succeed");
        uint256 before2 = c.getBalance(actor);
        assertTrue(before2 == amount, "balance must equal deposited amount");

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok2;
        try c.addToBalance{value: amount}() { ok2 = true; } catch { ok2 = false; }

        // GENERAL RULE: a completed deposit never decreases the caller's recorded balance.
        assertTrue(!ok2 || c.getBalance(actor) >= before2);
    }
}

