pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amt1, uint256 amt2, address actor) public {
        // Keep the domain WIDE: amt1 is near the uint256 ceiling so that ANY
        // small additional deposit overflows; the fuzzer still picks both amounts and the actor.
        vm.assume(actor != address(0) && actor != address(c));
        amt1 = bound(amt1, type(uint256).max - 2**160, type(uint256).max);
        amt2 = bound(amt2, 1, 2**160);

        // First deposit: an enormous amount that fits.
        vm.deal(actor, amt1);
        vm.prank(actor);
        c.addToBalance{value: amt1}();
        uint256 afterFirst = c.getBalance(actor);

        // Second deposit: guaranteed to overflow when added to the first.
        vm.deal(actor, amt2);
        vm.prank(actor);
        bool ok;
        try c.addToBalance{value: amt2}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: no admissible sequence of deposits may ever decrease
        // the recorded balance (monotonicity). The reference reverts on the
        // overflow and leaves the balance at `afterFirst`; the buggy version
        // silently wraps and drops the balance below `afterFirst`.
        assertTrue(c.getBalance(actor) >= afterFirst);
    }
}

