pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 seedBalance, uint256 amount, address actor) public {
        vm.assume(actor != address(c));
        // bring the recorded balance close to the maximum so an overflow is reachable
        seedBalance = bound(seedBalance, type(uint256).max / 2, type(uint256).max - 1);
        // any amount large enough to overflow the balance + amount sum
        amount = bound(amount, type(uint256).max - seedBalance, type(uint256).max);

        vm.deal(actor, seedBalance);
        vm.prank(actor);
        c.addToBalance{value: seedBalance}();

        vm.deal(actor, amount);
        vm.prank(actor);
        bool panicked = false;
        try c.addToBalance{value: amount}() {
            panicked = false;
        } catch Panic(uint256) {
            panicked = true;
        } catch {
            panicked = false;
        }
        assertTrue(!panicked);
    }
}

